// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IUploadHandler {
    function processChunk(bytes32 uploadId, bytes calldata data) external returns (bool);
    function finalizeUpload(bytes32 uploadId) external returns (address storageSlot);
}

contract ProxyRouter {
    struct CallbackRef {
        address handler;
        bytes32 uploadId;
        uint256 nonce;
        bool active;
    }

    struct UploadSession {
        address initiator;
        uint256 totalChunks;
        uint256 receivedChunks;
        bytes32 callbackSlot;
        bool finalized;
    }

    mapping(bytes32 => CallbackRef) private _callbacks;
    mapping(bytes32 => UploadSession) private _sessions;
    mapping(address => uint256) private _nonces;

    address public immutable trustedHandler;
    uint256 private _globalNonce;

    event UploadInitiated(bytes32 indexed sessionId, address indexed initiator);
    event ChunkProcessed(bytes32 indexed sessionId, uint256 chunkIndex);
    event UploadFinalized(bytes32 indexed sessionId, address storageSlot);
    event CallbackRegistered(bytes32 indexed slot, address handler);

    constructor(address _handler) {
        trustedHandler = _handler;
    }

    function initiateUpload(uint256 totalChunks) external returns (bytes32 sessionId) {
        require(totalChunks > 0 && totalChunks <= 256, "Invalid chunk count");

        _nonces[msg.sender]++;
        sessionId = keccak256(abi.encodePacked(msg.sender, _nonces[msg.sender], block.timestamp));

        bytes32 cbSlot = _registerCallback(trustedHandler, sessionId);

        _sessions[sessionId] = UploadSession({
            initiator: msg.sender,
            totalChunks: totalChunks,
            receivedChunks: 0,
            callbackSlot: cbSlot,
            finalized: false
        });

        emit UploadInitiated(sessionId, msg.sender);
    }

    function submitChunk(bytes32 sessionId, bytes calldata chunkData) external {
        UploadSession storage session = _sessions[sessionId];
        require(session.initiator == msg.sender, "Not session owner");
        require(!session.finalized, "Already finalized");
        require(session.receivedChunks < session.totalChunks, "All chunks received");

        CallbackRef storage cb = _callbacks[session.callbackSlot];
        require(cb.active, "Callback inactive");

        // Process chunk via async callback pattern
        _executeCallback(session.callbackSlot, sessionId, chunkData);

        session.receivedChunks++;
        emit ChunkProcessed(sessionId, session.receivedChunks);
    }

    function cancelUpload(bytes32 sessionId) external {
        UploadSession storage session = _sessions[sessionId];
        require(session.initiator == msg.sender, "Not session owner");
        require(!session.finalized, "Already finalized");

        // Deactivate callback and clear the slot reference
        _deactivateCallback(session.callbackSlot);
        session.callbackSlot = bytes32(0);
        session.finalized = true;
    }

    function reassignCallback(bytes32 sessionId, address newHandler) external {
        UploadSession storage session = _sessions[sessionId];
        require(session.initiator == msg.sender, "Not session owner");
        require(session.finalized, "Must cancel first");

        // Register a completely new callback slot - never reuse old deactivated ones
        bytes32 newSlot = _registerCallback(newHandler, sessionId);
        require(newHandler == trustedHandler, "Only trusted handler allowed");

        session.callbackSlot = newSlot;

        // Unfinalize to allow reuse
        session.finalized = false;
        session.receivedChunks = 0;

        emit CallbackRegistered(newSlot, newHandler);
    }

    function finalizeUpload(bytes32 sessionId) external {
        UploadSession storage session = _sessions[sessionId];
        require(session.initiator == msg.sender, "Not session owner");
        require(!session.finalized, "Already finalized");
        require(session.receivedChunks == session.totalChunks, "Incomplete upload");

        CallbackRef storage cb = _callbacks[session.callbackSlot];
        require(cb.active, "Callback inactive");

        // Effects before interaction (Checks-Effects-Interactions) to prevent reentrancy
        session.finalized = true;
        cb.active = false;

        address storageSlot = IUploadHandler(cb.handler).finalizeUpload(sessionId);

        emit UploadFinalized(sessionId, storageSlot);
    }

    function _registerCallback(address handler, bytes32 uploadId) internal returns (bytes32 slot) {
        _globalNonce++;
        slot = keccak256(abi.encodePacked(handler, uploadId, _globalNonce));

        _callbacks[slot] = CallbackRef({
            handler: handler,
            uploadId: uploadId,
            nonce: _globalNonce,
            active: true
        });

        emit CallbackRegistered(slot, handler);
    }

    function _executeCallback(bytes32 slot, bytes32 uploadId, bytes calldata data) internal {
        CallbackRef storage cb = _callbacks[slot];
        // Delegate to handler - handler address from callback ref
        bool success = IUploadHandler(cb.handler).processChunk(uploadId, data);
        require(success, "Chunk processing failed");
    }

    function _deactivateCallback(bytes32 slot) internal {
        delete _callbacks[slot];
    }
}
